(function(){"use strict";let activeProjects=[],activeCertificates=[];async function _initCore(){updateYearsActiveCounter();await loadDynamicProjects();await loadDynamicCertificates();initEvents();initRevealAnimations();initAnalytics();};if(document.readyState==='loading'){window.addEventListener('DOMContentLoaded',_initCore);}else{_initCore();}function updateYearsActiveCounter(){const years=new Date().getFullYear()-2017;const el=document.getElementById('statYearsCounter');if(el){el.setAttribute('data-counter',years);el.textContent=years+'+';}}async function loadDynamicProjects(){let saved=localStorage.getItem('syauqi_projects_cms');if(saved){try{activeProjects=JSON.parse(saved);}catch(e){}}if(window.firebaseDb){try{const snapshot=await window.firebaseHelpers.getDocs(window.firebaseHelpers.collection(window.firebaseDb,"projects"));const remote=[];snapshot.forEach(d=>remote.push({id:d.id,...d.data()}));if(remote.length>0){remote.sort((a,b)=>(a.order??0)-(b.order??0));activeProjects=remote;}}catch(e){console.warn("Firestore fetch error:",e);}}if(!activeProjects||activeProjects.length===0){activeProjects=window.DEFAULT_PROJECTS||[];}renderProjectsUI(activeProjects);}function getCategoryLabel(cat){const map={'saas':'Web App','website':'Website','automation':'Tools AI'};return map[cat]||'Project';}function renderProjectsUI(projects){const projCounterEl=document.getElementById('statProjectsCounter');if(projCounterEl){projCounterEl.setAttribute('data-counter',projects.length);projCounterEl.textContent=projects.length+'+';}const container=document.getElementById('projectsGrid');if(!container)return;container.innerHTML='';projects.forEach(p=>{const article=document.createElement('article');article.className="project-card group rounded-2xl border border-[var(--border-color)] bg-[var(--bg-panel)] p-6 sm:p-7 flex flex-col justify-between hover:border-[var(--border-accent)] transition-all shadow-sm hover:shadow-md cursor-pointer overflow-hidden";article.setAttribute('data-category',p.category||'saas');article.onclick=()=>openProjectDetailModal(p.id);const catLabel=getCategoryLabel(p.category||'saas');const tagsList=(Array.isArray(p.tags)?p.tags:(p.tags||'').split(','));const imageBlockHtml=p.imageUrl?`<div class="mb-4 overflow-hidden rounded-xl border border-[var(--border-color)] h-44 sm:h-52 w-full"><img src="${p.imageUrl}" alt="${p.title}" class="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"></div>`:'';article.innerHTML=`<div>${imageBlockHtml}<div class="flex items-center justify-between font-mono text-xs text-[var(--text-muted)] mb-3"><span class="uppercase font-bold text-[var(--accent)] text-[10px] px-2 py-0.5 rounded bg-[var(--bg-panel-alt)] border border-[var(--border-color)]">${p.badge||catLabel}</span><span class="px-2 py-0.5 rounded border border-[var(--border-color)] bg-[var(--bg-panel-alt)] text-[var(--text-muted)] text-[10px] font-semibold uppercase tracking-wider">${catLabel}</span></div><h3 class="font-display font-bold text-2xl uppercase text-[var(--text-main)] mb-2 group-hover:text-[var(--accent)] transition-colors">${p.title}</h3><p class="text-xs sm:text-sm text-[var(--text-muted)] leading-relaxed line-clamp-3 mb-4">${p.problemSolution||''}</p><div class="flex flex-wrap gap-1.5 mb-4">${tagsList.map(t=>`<span class="px-2.5 py-0.5 font-mono text-[11px] rounded-md border border-[var(--border-color)] bg-[var(--bg-panel-alt)] text-[var(--text-main)]">${t.trim()}</span>`).join('')}</div></div><div class="pt-4 border-t border-[var(--border-color)] flex items-center justify-between font-mono text-xs mt-auto"><span class="text-emerald-500 font-semibold">${p.metric||'Live System'}</span><button class="px-3.5 py-1.5 font-mono text-xs font-bold uppercase rounded-lg bg-[var(--accent)] text-[var(--accent-ink)] group-hover:opacity-90 transition-all flex items-center gap-1"><span data-t-en="See Details" data-t-id="Lihat Detail">See Details</span> →</button></div>`;container.appendChild(article);});}window.openProjectDetailModal=function(id){const proj=activeProjects.find(p=>p.id===id);if(!proj)return;const modal=document.getElementById('projectDetailModal');if(!modal)return;const imgContainer=document.getElementById('modalProjImgContainer');const img=document.getElementById('modalProjImg');if(proj.imageUrl){img.src=proj.imageUrl;imgContainer.classList.remove('hidden');}else{imgContainer.classList.add('hidden');}const catLabel=getCategoryLabel(proj.category||'saas');document.getElementById('modalProjBadge').textContent=proj.badge||catLabel;document.getElementById('modalProjCategory').textContent=catLabel;document.getElementById('modalProjTitle').textContent=proj.title;document.getElementById('modalProjSubtitle').textContent=proj.subtitle||'Custom delivery & architecture.';document.getElementById('modalProjDesc').textContent=proj.problemSolution||'';const tagsContainer=document.getElementById('modalProjTags');tagsContainer.innerHTML='';const tagsList=(Array.isArray(proj.tags)?proj.tags:(proj.tags||'').split(','));tagsList.forEach(t=>{const span=document.createElement('span');span.className="px-3 py-1 font-mono text-xs rounded-md border border-[var(--border-color)] bg-[var(--bg-panel-alt)] text-[var(--text-main)]";span.textContent=t.trim();tagsContainer.appendChild(span);});document.getElementById('modalProjMetric').textContent=proj.metric||'Successful Launch';const demoBtn=document.getElementById('modalProjDemoBtn');demoBtn.href=proj.demoUrl||'#contact';modal.classList.remove('hidden');setTimeout(()=>modal.classList.remove('opacity-0'),10);};window.closeProjectDetailModal=function(){const modal=document.getElementById('projectDetailModal');if(!modal)return;modal.classList.add('opacity-0');setTimeout(()=>modal.classList.add('hidden'),300);};async function loadDynamicCertificates(){let saved=localStorage.getItem('syauqi_certs_cms');if(saved){try{activeCertificates=JSON.parse(saved);}catch(e){}}if(window.firebaseDb){try{const snapshot=await window.firebaseHelpers.getDocs(window.firebaseHelpers.collection(window.firebaseDb,"certificates"));const remote=[];snapshot.forEach(d=>remote.push({id:d.id,...d.data()}));if(remote.length>0){remote.sort((a,b)=>(a.order??0)-(b.order??0));activeCertificates=remote;}}catch(e){console.warn("Firestore certs error:",e);}}if(!activeCertificates||activeCertificates.length===0){activeCertificates=window.DEFAULT_CERTIFICATES||[];}renderCertificatesUI(activeCertificates);}function renderCertificatesUI(certs){const certCounterEl=document.getElementById('statCertsCounter');if(certCounterEl){certCounterEl.setAttribute('data-counter',certs.length);certCounterEl.textContent=certs.length+'+';}const container=document.getElementById('certsGrid');if(!container)return;container.innerHTML='';certs.forEach(c=>{const div=document.createElement('div');div.className="p-6 rounded-2xl border border-[var(--border-color)] bg-[var(--bg-panel)] space-y-4 hover:border-[var(--border-accent)] transition-all shadow-sm overflow-hidden";const certImageHtml=c.imageUrl?`<div class="overflow-hidden rounded-xl border border-[var(--border-color)] h-40 w-full mb-3"><img src="${c.imageUrl}" alt="${c.title}" class="w-full h-full object-cover"></div>`:'';div.innerHTML=`${certImageHtml}<div class="flex items-center justify-between font-mono text-xs"><span class="px-2.5 py-0.5 rounded bg-emerald-500/10 text-[var(--accent)] border border-emerald-500/20 font-bold">${c.issueDate||'2024'}</span><span class="text-[var(--text-muted)]">${c.issuer||'Official Issuer'}</span></div><div><h3 class="font-display font-bold text-2xl uppercase text-[var(--text-main)] mb-1">${c.title}</h3><p class="text-xs text-[var(--text-muted)] leading-relaxed mt-2">${c.description||''}</p></div><div class="pt-4 border-t border-[var(--border-color)] flex items-center justify-between font-mono text-xs"><span class="text-[var(--text-muted)]" data-t-en="Verified Credential" data-t-id="Sertifikat Resmi">Verified Credential</span><a href="${c.credentialUrl||'#'}" target="_blank" class="text-[var(--accent)] hover:underline font-bold" data-t-en="See Details →" data-t-id="Lihat Detail →">See Details →</a></div>`;container.appendChild(div);});}function getCurrentLang(){return document.documentElement.getAttribute('data-lang')||'en';}function initEvents(){window.addEventListener('scroll',()=>{const winScroll=document.body.scrollTop||document.documentElement.scrollTop;const height=document.documentElement.scrollHeight-document.documentElement.clientHeight;const scrolled=(winScroll/height)*100;const progress=document.getElementById('scrollProgress');if(progress)progress.style.width=scrolled+'%';});let currentLang='en';const langToggleBtn=document.getElementById('langToggle');if(langToggleBtn){langToggleBtn.addEventListener('click',()=>{currentLang=currentLang==='en'?'id':'en';document.documentElement.setAttribute('data-lang',currentLang);document.documentElement.setAttribute('lang',currentLang);document.querySelectorAll('[data-t-en]').forEach(el=>{const text=currentLang==='en'?el.getAttribute('data-t-en'):el.getAttribute('data-t-id');if(text)el.innerHTML=text;});langToggleBtn.textContent=currentLang==='en'?'EN':'ID';const activeOrnType=window._activeOrnType||'web';setHeroOrnament(activeOrnType);const activeEstType=window._activeEstType||'landing';setEstimator(activeEstType);});}let currentTheme='light';const themeToggleBtn=document.getElementById('themeToggle');if(themeToggleBtn){themeToggleBtn.addEventListener('click',()=>{currentTheme=currentTheme==='light'?'dark':'light';document.documentElement.setAttribute('data-theme',currentTheme);if(currentTheme==='dark')document.documentElement.classList.add('dark');else document.documentElement.classList.remove('dark');});}const menuToggle=document.getElementById('menuToggle');const mobileMenu=document.getElementById('mobileMenu');if(menuToggle&&mobileMenu){menuToggle.addEventListener('click',()=>{mobileMenu.classList.toggle('hidden');mobileMenu.classList.toggle('flex');});mobileMenu.querySelectorAll('a').forEach(link=>{link.addEventListener('click',()=>{mobileMenu.classList.add('hidden');mobileMenu.classList.remove('flex');});});}const filterButtons=document.querySelectorAll('.filter-btn');filterButtons.forEach(btn=>{btn.addEventListener('click',()=>{const filter=btn.getAttribute('data-filter');// Update active state
filterButtons.forEach(b=>{b.classList.remove('border-[var(--accent)]','bg-[var(--accent)]','text-[var(--accent-ink)]');b.classList.add('border-[var(--border-color)]','bg-[var(--bg-panel)]','text-[var(--text-muted)]');});btn.classList.remove('border-[var(--border-color)]','bg-[var(--bg-panel)]','text-[var(--text-muted)]');btn.classList.add('border-[var(--accent)]','bg-[var(--accent)]','text-[var(--accent-ink)]');// Filter cards
document.querySelectorAll('.project-card').forEach(card=>{if(filter==='all'||card.getAttribute('data-category')===filter){card.style.display='block';}else{card.style.display='none';}});// Scroll active filter button into view on mobile
btn.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'});});});const leadForm=document.getElementById('leadForm');if(leadForm){leadForm.addEventListener('submit',(e)=>{e.preventDefault();showToast('Checklist request received! PDF will be sent to your email.');leadForm.reset();});}}function initRevealAnimations(){const counters=document.querySelectorAll('[data-counter]');const counterObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){const el=entry.target;const target=parseInt(el.getAttribute('data-counter'));const suffix=el.getAttribute('data-suffix')||'';const duration=1400;const start=performance.now();function update(now){const elapsed=now-start;const progress=Math.min(elapsed/duration,1);const eased=1-Math.pow(1-progress,3);const current=Math.round(eased*target);el.textContent=current+suffix;if(progress<1)requestAnimationFrame(update);}requestAnimationFrame(update);counterObserver.unobserve(el);}});},{threshold:0.4});counters.forEach(c=>counterObserver.observe(c));const statCards=document.querySelectorAll('.stat-reveal');const statObserver=new IntersectionObserver((entries)=>{entries.forEach((entry,i)=>{if(entry.isIntersecting){setTimeout(()=>entry.target.classList.add('animated'),i*60);statObserver.unobserve(entry.target);}});},{threshold:0.15});statCards.forEach(c=>statObserver.observe(c));const featCards=document.querySelectorAll('.feat-reveal');const featObserver=new IntersectionObserver((entries)=>{entries.forEach(entry=>{if(entry.isIntersecting){entry.target.classList.add('animated');featObserver.unobserve(entry.target);}});},{threshold:0.15});featCards.forEach(c=>featObserver.observe(c));}window.setHeroOrnament=function(type){window._activeOrnType=type;const lang=getCurrentLang();const data={web:{en:{title:"Custom Web Application",badge:"3-7 Days Delivery",desc:"Tailored web apps built for your exact business requirements, complete with secure database, admin panel, and mobile responsiveness.",tags:["React / Next.js","Node.js","PostgreSQL / Supabase"]},id:{title:"Web App Kustom",badge:"3-7 Hari Pengerjaan",desc:"Web app kustom sesuai kebutuhan bisnis kamu, dilengkapi database aman, panel admin, dan tampilan mobile responsif.",tags:["React / Next.js","Node.js","PostgreSQL / Supabase"]}},landing:{en:{title:"High-Speed Landing Page",badge:"2-4 Days Delivery",desc:"Sleek, high-converting marketing landing page designed to load in under 1 second on mobile and convert traffic into leads.",tags:["Webflow / HTML5","Tailwind CSS","SEO Schema"]},id:{title:"Landing Page Cepat",badge:"2-4 Hari Pengerjaan",desc:"Landing page marketing yang cepat dan elegan, dirancang agar bisa mengubah traffic jadi calon klien.",tags:["Webflow / HTML5","Tailwind CSS","SEO Schema"]}},ai:{en:{title:"Tools AI Integration",badge:"1-3 Days Delivery",desc:"Integrating smart AI models (Claude 3.5 & GPT-4o), prompt engineering, and automated workflows into your web apps.",tags:["Claude 3.5 API","OpenAI API","n8n Workflows"]},id:{title:"Integrasi Tools AI",badge:"1-3 Hari Pengerjaan",desc:"Integrasi model AI canggih (Claude 3.5 & GPT-4o), prompt engineering, dan otomasi workflow ke dalam aplikasi kamu.",tags:["Claude 3.5 API","OpenAI API","n8n Workflows"]}}}[type];if(!data)return;const d=data[lang]||data.en;document.getElementById('ornTitle').textContent=d.title;document.getElementById('ornBadge').textContent=d.badge;document.getElementById('ornDesc').textContent=d.desc;const tagsContainer=document.getElementById('ornTags');tagsContainer.innerHTML='';d.tags.forEach(t=>{const span=document.createElement('span');span.className="px-2 py-0.5 rounded bg-[var(--bg-panel)] border border-[var(--border-color)] text-[var(--text-main)]";span.textContent=t;tagsContainer.appendChild(span);});['Web','Landing','Ai'].forEach(k=>{const btn=document.getElementById('ornTab'+k);if(btn)btn.className="px-3 py-1.5 font-mono text-xs rounded-lg border border-[var(--border-color)] bg-[var(--bg-panel-alt)] text-[var(--text-muted)] hover:border-[var(--accent)] transition-all";});const activeBtn=document.getElementById('ornTab'+(type==='web'?'Web':type==='landing'?'Landing':'Ai'));if(activeBtn)activeBtn.className="px-3 py-1.5 font-mono text-xs rounded-lg border border-[var(--accent)] bg-[var(--accent)] text-[var(--accent-ink)] font-semibold transition-all";};window.setEstimator=function(type){window._activeEstType=type;const lang=getCurrentLang();const data={landing:{en:{turnaround:"3-5 Days",included:"Design, Fast Slicing &amp; Mobile Responsive"},id:{turnaround:"3-5 Hari",included:"Desain, Slicing Cepat &amp; Mobile Responsif"}},webapp:{en:{turnaround:"7-14 Days",included:"Database, Admin Access &amp; Custom Features"},id:{turnaround:"7-14 Hari",included:"Database, Akses Admin &amp; Fitur Kustom"}},automation:{en:{turnaround:"2-4 Days",included:"Tools AI Integration &amp; Workflow Setup"},id:{turnaround:"2-4 Hari",included:"Integrasi Tools AI &amp; Pengaturan Workflow"}}}[type];if(!data)return;const d=data[lang]||data.en;document.getElementById('estTurnaround').innerHTML=d.turnaround;document.getElementById('estIncluded').innerHTML=d.included;['Landing','App','Auto'].forEach(k=>{const btn=document.getElementById('estBtn'+k);if(btn)btn.className="px-4 py-2 font-mono text-xs rounded-lg border border-[var(--border-color)] bg-[var(--bg-panel)] text-[var(--text-muted)] hover:border-[var(--accent)] transition-all";});const activeBtn=document.getElementById('estBtn'+(type==='landing'?'Landing':type==='webapp'?'App':'Auto'));if(activeBtn)activeBtn.className="px-4 py-2 font-mono text-xs rounded-lg border border-[var(--accent)] bg-[var(--accent)] text-[var(--accent-ink)] font-bold transition-all";};window.copyEmail=function(email){navigator.clipboard.writeText(email);showToast('Email address copied to clipboard!');};function showToast(message){const toast=document.getElementById('toast');if(!toast)return;const msgEl=document.getElementById('toastMsg');if(msgEl)msgEl.textContent=message;toast.classList.add('show');setTimeout(()=>{toast.classList.remove('show');},3500);}function initAnalytics(){const STORAGE_KEY='syauqi_analytics_v1';function getUrlParam(param){const urlParams=new URLSearchParams(window.location.search);return urlParams.get(param);}function detectReferrerChannel(){const utmSource=getUrlParam('utm_source')||getUrlParam('ref')||getUrlParam('source');if(utmSource){const s=utmSource.toLowerCase();if(s.includes('ig')||s.includes('instagram'))return 'Instagram';if(s.includes('thread')||s.includes('threads'))return 'Threads';if(s.includes('yt')||s.includes('youtube'))return 'YouTube';if(s.includes('google'))return 'Google Search';if(s.includes('li')||s.includes('linkedin'))return 'LinkedIn';}const ref=document.referrer.toLowerCase();if(ref.includes('instagram.com'))return 'Instagram';if(ref.includes('threads.net'))return 'Threads';if(ref.includes('youtube.com')||ref.includes('youtu.be'))return 'YouTube';if(ref.includes('google.com'))return 'Google Search';if(ref.includes('linkedin.com'))return 'LinkedIn';if(ref.includes('t.co')||ref.includes('twitter.com'))return 'Twitter/X';return 'Direct / Bookmark';}function getDeviceType(){const ua=navigator.userAgent;if(/(tablet|ipad|playbook|silk)|(android(?!.*mobi))/i.test(ua))return 'Tablet';if(/Mobile|iP(hone|od)|Android|BlackBerry|IEMobile|Kindle|Silk-Accelerated|(hpw|web)OS|Opera M(obi|ini)/i.test(ua))return 'Mobile';return 'Desktop';}function loadStore(){let store=localStorage.getItem(STORAGE_KEY);if(!store){store={visitorId:'vis_'+Math.random().toString(36).substring(2,9),sessions:[],clicks:[],currentSessionStart:Date.now()};localStorage.setItem(STORAGE_KEY,JSON.stringify(store));}else{try{store=JSON.parse(store);}catch(e){store={visitorId:'vis_'+Math.random().toString(36).substring(2,9),sessions:[],clicks:[],currentSessionStart:Date.now()};}}return store;}const currentStore=loadStore();const currentChannel=detectReferrerChannel();const currentDevice=getDeviceType();const sessionStartTime=Date.now();const newSession={id:'sess_'+Math.random().toString(36).substring(2,9),channel:currentChannel,device:currentDevice,duration:1,timestamp:sessionStartTime};currentStore.sessions.unshift(newSession);if(currentStore.sessions.length>200)currentStore.sessions.pop();localStorage.setItem(STORAGE_KEY,JSON.stringify(currentStore));setInterval(()=>{const store=loadStore();const activeSess=store.sessions.find(s=>s.id===newSession.id);if(activeSess){activeSess.duration=Math.max(1,Math.floor((Date.now()-sessionStartTime)/1000));localStorage.setItem(STORAGE_KEY,JSON.stringify(store));}},3000);document.addEventListener('click',(e)=>{const clickable=e.target.closest('[data-track-id], a, button');if(!clickable)return;const trackId=clickable.getAttribute('data-track-id')||clickable.id||clickable.getAttribute('href')||clickable.innerText;const textLabel=clickable.innerText?clickable.innerText.trim().substring(0,35):'Action Click';const store=loadStore();store.clicks.unshift({id:'clk_'+Math.random().toString(36).substring(2,9),channel:currentChannel,element:trackId,text:textLabel,timestamp:Date.now(),device:currentDevice});if(store.clicks.length>300)store.clicks.pop();localStorage.setItem(STORAGE_KEY,JSON.stringify(store));});}})();
